def find_kth_smallest_exclusive(N: int, M: int, K: int) -> int:
    def count_divisible_by_either(x, n, m):
        cnt_n = x // n
        cnt_m = x // m
        cnt_d = x // (n * m)
        return cnt_n + cnt_m - 2 * cnt_d

    l = 1
    r = 10**18

    while l < r:
        mid = (l + r) // 2
        cnt = count_divisible_by_either(mid, N, M)
        if cnt < K:
            l = mid + 1
        else:
            r = mid

    return l
